using UnityEngine;using UnityEditor;
[CustomEditor(typeof(CityTrafficSignal)),CanEditMultipleObjects]public class CityTrafficSignalEditor:Editor{
public override void OnInspectorGUI(){DrawDefaultInspector();GUILayout.BeginHorizontal();foreach(var s in new[]{CityTrafficSignal.SignalState.Red,CityTrafficSignal.SignalState.Yellow,CityTrafficSignal.SignalState.Green,CityTrafficSignal.SignalState.Off})if(GUILayout.Button(s.ToString()))foreach(CityTrafficSignal c in targets){Undo.RecordObject(c,"Signal light");c.SetState(s);EditorUtility.SetDirty(c);PrefabUtility.RecordPrefabInstancePropertyModifications(c);}GUILayout.EndHorizontal();EditorGUILayout.HelpBox("Edit the Signal prefab to set defaults for all connected instances. Automatic Cycle runs in Play mode. Use Red, Yellow, Green or Off from your game scripts.",MessageType.Info);}}
